window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-76f9a356785d43ff"]={"versions": [{"id": "FIG-76f9a356785d43ff", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilablaufs innerhalb der AUTOSAR E2E-Bibliothek (E2E Protocol, Profile 22). Das Diagramm stellt den Teilschritt „Read CRC“ der Prüffunktion <code>E2E_P22Check()</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontext/Aktivitätsrahmen: Funktion <code>E2E_P22Check()</code> (gekennzeichnet über ein abgerundetes Kasten-Symbol mit Schleifen-/Subaktivitäts-Icon oben links).\n</li><li>Eingangsdaten / Konfigurationsobjekt: Array <code>Data[]</code> sowie Konfigurationsstrukturkomponente <code>Config-&gt;Offset</code>.\n</li><li>Ausgangs-/Zwischengröße: Lokale Variable <code>ReceivedCRC</code>.\n</li><li>Kontrollflusselemente: Startknoten (Initial Node), eine Aktionsstufe (Action Node) und ein Endknoten (Activity Final Node).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten.\n</li><li>In der einzigen sequenziellen Aktion wird das Byte an der berechneten Bit-Offset-Position im Datenarray gelesen und einer lokalen Variablen zugewiesen: <code>Copy byte Data[Config-&gt;Offset/8] to local variable ReceivedCRC</code>.\n</li><li>Der Ablauf erreicht unmittelbar den Endknoten des Teilschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation für Implementierungen von E2E Profile 22 gemäß PRS_E2E_00537. Das Offset ist in Bits konfiguriert und wird durch Division durch 8 (<code>Config-&gt;Offset/8</code>) in einen Byte-Index umgerechnet. Entwickler müssen sicherstellen, dass <code>Data</code> mindestens die durch <code>Config-&gt;Offset/8</code> adressierte Länge besitzt, um Out-of-Bounds-Zugriffe vor der CRC-Berechnung und -Prüfung zu vermeiden.</p>"}, {"id": "FIG-ab018ce701547230", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilablaufs innerhalb der AUTOSAR E2E-Bibliothek (E2E Protocol, Profile 22). Das Diagramm stellt den Teilschritt „Read CRC“ der Prüffunktion <code>E2E_P22Check()</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontext/Aktivitätsrahmen: Funktion <code>E2E_P22Check()</code> (gekennzeichnet über ein abgerundetes Kasten-Symbol mit Schleifen-/Subaktivitäts-Icon oben links).\n</li><li>Eingangsdaten / Konfigurationsobjekt: Array <code>Data[]</code> sowie Konfigurationsstrukturkomponente <code>Config-&gt;Offset</code>.\n</li><li>Ausgangs-/Zwischengröße: Lokale Variable <code>ReceivedCRC</code>.\n</li><li>Kontrollflusselemente: Startknoten (Initial Node), eine Aktionsstufe (Action Node) und ein Endknoten (Activity Final Node).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten.\n</li><li>In der einzigen sequenziellen Aktion wird das Byte an der berechneten Bit-Offset-Position im Datenarray gelesen und einer lokalen Variablen zugewiesen: <code>Copy byte Data[Config-&gt;Offset/8] to local variable ReceivedCRC</code>.\n</li><li>Der Ablauf erreicht unmittelbar den Endknoten des Teilschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation für Implementierungen von E2E Profile 22 gemäß PRS_E2E_00537. Das Offset ist in Bits konfiguriert und wird durch Division durch 8 (<code>Config-&gt;Offset/8</code>) in einen Byte-Index umgerechnet. Entwickler müssen sicherstellen, dass <code>Data</code> mindestens die durch <code>Config-&gt;Offset/8</code> adressierte Länge besitzt, um Out-of-Bounds-Zugriffe vor der CRC-Berechnung und -Prüfung zu vermeiden.</p>"}, {"id": "FIG-9197089926af1787", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilablaufs innerhalb der AUTOSAR E2E-Bibliothek (E2E Protocol, Profile 22). Das Diagramm stellt den Teilschritt „Read CRC“ der Prüffunktion <code>E2E_P22Check()</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontext/Aktivitätsrahmen: Funktion <code>E2E_P22Check()</code> (gekennzeichnet über ein abgerundetes Kasten-Symbol mit Schleifen-/Subaktivitäts-Icon oben links).\n</li><li>Eingangsdaten / Konfigurationsobjekt: Array <code>Data[]</code> sowie Konfigurationsstrukturkomponente <code>Config-&gt;Offset</code>.\n</li><li>Ausgangs-/Zwischengröße: Lokale Variable <code>ReceivedCRC</code>.\n</li><li>Kontrollflusselemente: Startknoten (Initial Node), eine Aktionsstufe (Action Node) und ein Endknoten (Activity Final Node).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten.\n</li><li>In der einzigen sequenziellen Aktion wird das Byte an der berechneten Bit-Offset-Position im Datenarray gelesen und einer lokalen Variablen zugewiesen: <code>Copy byte Data[Config-&gt;Offset/8] to local variable ReceivedCRC</code>.\n</li><li>Der Ablauf erreicht unmittelbar den Endknoten des Teilschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation für Implementierungen von E2E Profile 22 gemäß PRS_E2E_00537. Das Offset ist in Bits konfiguriert und wird durch Division durch 8 (<code>Config-&gt;Offset/8</code>) in einen Byte-Index umgerechnet. Entwickler müssen sicherstellen, dass <code>Data</code> mindestens die durch <code>Config-&gt;Offset/8</code> adressierte Länge besitzt, um Out-of-Bounds-Zugriffe vor der CRC-Berechnung und -Prüfung zu vermeiden.</p>"}], "trans": [{"from": "FIG-76f9a356785d43ff", "to": "FIG-ab018ce701547230", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ab018ce701547230", "to": "FIG-9197089926af1787", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
